def solve(intervals):
    if not intervals:
        return []

    # Sort intervals based on the start value
    intervals.sort()
    merged = [intervals[0]]

    for current in intervals[1:]:
       last = merged[-1]
        if current[0] <= last[1]:
            # Overlapping or touching, merge them
            merged[-1] = [last[0], max(last[1], current[1])]
        else:
            merged.append(current)

    return merged
